import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root group
  const root = new Group();

  // Geometry sized to atlas region aspect ratio (512:320 = 1.6)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Texture node and material
  const texNode = texture();
  const material = new MeshBasicNodeMaterial();
  material.map = texNode;

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texNode.value = tex;
      material.needsUpdate = true;
    });
  }

  // Text content handling
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.intent?.visualSpec?.colors?.paper) ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // Billboard handler: face camera each frame
  root.userData.handlers = {
    render: (renderer, scene, camera) => {
      mesh.lookAt(camera.position);
    },
  };

  // Cleanup
  root.userData.cleanup = () => {
    // No GSAP timelines used, but kill any if added later
    // Dispose three
    material.dispose();
    geometry.dispose();
    // Text objects will be disposed by Three.js when group is removed
  };

  return root;
}
